<script setup lang="ts">
import * as echarts from 'echarts';import {nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
const props=defineProps<{strategy:any[];benchmark?:any[];drawdown?:any[]}>();const root=ref<HTMLDivElement>();let chart:echarts.ECharts|null=null
function render(){if(!root.value||!props.strategy?.length)return;chart??=echarts.init(root.value);const labels=props.strategy.map(x=>String(x.timestamp).slice(0,10));chart.setOption({animation:false,backgroundColor:'transparent',tooltip:{trigger:'axis',backgroundColor:'#111a26',borderColor:'#293648',textStyle:{color:'#dce6f2'}},legend:{data:['Strategy','Benchmark','Drawdown'],textStyle:{color:'#8fa1b5'}},grid:[{left:58,right:48,top:36,height:'56%'},{left:58,right:48,top:'73%',height:'15%'}],xAxis:[{type:'category',data:labels,axisLabel:{color:'#687b90'},axisLine:{lineStyle:{color:'#263647'}}},{type:'category',gridIndex:1,data:labels,axisLabel:{show:false},axisLine:{lineStyle:{color:'#263647'}}}],yAxis:[{scale:true,axisLabel:{color:'#687b90'},splitLine:{lineStyle:{color:'#192735'}}},{gridIndex:1,axisLabel:{color:'#687b90',formatter:'{value}%'},splitLine:{show:false}}],dataZoom:[{type:'inside',xAxisIndex:[0,1]}],series:[{name:'Strategy',type:'line',data:props.strategy.map(x=>x.equity),showSymbol:false,lineStyle:{width:2,color:'#3bd5b3'}},{name:'Benchmark',type:'line',data:(props.benchmark||[]).map(x=>x.equity),showSymbol:false,lineStyle:{width:1.5,color:'#6c8cff',type:'dashed'}},{name:'Drawdown',type:'line',xAxisIndex:1,yAxisIndex:1,data:(props.drawdown||[]).map(x=>x.drawdown),showSymbol:false,lineStyle:{width:1,color:'#f06a7c'},areaStyle:{color:'#f06a7c22'}}]},true)}
const resize=()=>chart?.resize();onMounted(()=>{nextTick(render);window.addEventListener('resize',resize)});watch(()=>[props.strategy,props.benchmark,props.drawdown],()=>nextTick(render),{deep:true});onBeforeUnmount(()=>{window.removeEventListener('resize',resize);chart?.dispose()})
</script><template><div ref="root" class="performance-chart"></div></template>
